INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch13$PT137-S3-Q5$batch13$, 137, 3, 5, $batch13$Role$batch13$, $batch13$Dogs learn best when they are trained using both voice commands and hand signals. After all, a recent study shows that dogs who were trained using both voice commands and hand signals were twice as likely to obey as were dogs who were trained using only voice commands.$batch13$, $batch13$The claim that dogs learn best when they are trained using both voice commands and hand signals figures in the argument in which one of the following ways?$batch13$, $batch13$D$batch13$, true, $batch13$Batch 13; question text from local bank.$batch13$ FROM lr_sections s WHERE s.preptest=137 AND s.section=3 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch13$PT137-S3-Q5$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$A$batch13$, $batch13$It is an explicit premise of the argument.$batch13$, $batch13$Wrong Role$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT137-S3-Q5$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$A$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$B$batch13$, $batch13$It is an implicit assumption of the argument.$batch13$, $batch13$Wrong Role$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT137-S3-Q5$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$B$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$C$batch13$, $batch13$It is a statement of background information offered to help facilitate understanding the issue in the argument.$batch13$, $batch13$Wrong Role$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT137-S3-Q5$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$C$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$D$batch13$, $batch13$It is a statement that the argument claims is supported by the study.$batch13$, $batch13$Correct$batch13$, true FROM lr_questions q WHERE q.qid=$batch13$PT137-S3-Q5$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$D$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$E$batch13$, $batch13$It is an intermediate conclusion that is offered as direct support for the argument's main conclusion.$batch13$, $batch13$Wrong Role$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT137-S3-Q5$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$E$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch13$PT137-S3-Q5$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch13$Conclusion$batch13$, $batch13$Dogs learn best when trained with both voice commands and hand signals.$batch13$), (1, $batch13$Evidence$batch13$, $batch13$In a recent study, dogs trained with both were twice as likely to obey as dogs trained with voice commands only.$batch13$), (2, $batch13$Evaluate$batch13$, $batch13$"After all" introduces the study as the reason for the first sentence. The first sentence is the claim the study is said to support, and nothing else in the argument rests on it.$batch13$), (3, $batch13$Goal$batch13$, $batch13$A claim the argument says the study supports.$batch13$)) v(position,label,body) WHERE q.qid=$batch13$PT137-S3-Q5$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch13$A$batch13$, $batch13$It's supported, not a premise.$batch13$), ($batch13$B$batch13$, $batch13$It's stated outright, so it isn't an implicit assumption.$batch13$), ($batch13$C$batch13$, $batch13$It isn't background. It's the point of the argument.$batch13$), ($batch13$D$batch13$, $batch13$The study is offered as the support for this claim.$batch13$), ($batch13$E$batch13$, $batch13$There's no other conclusion for it to support. It is the main conclusion.$batch13$)) v(letter,body) WHERE q.qid=$batch13$PT137-S3-Q5$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
